import Foundation
import XCTest
@testable import ScionicMerkleTree

/// WIRE-LEVEL UNIFICATION TESTS: golden CBOR vectors generated by the DEPLOYED
/// Go implementation — github.com/HORNET-Storage/Scionic-Merkle-Tree/v2 v2.2.6,
/// the version pinned by HORNETS-Nostr-Relay and hdk-nostr-go — decoded and
/// verified by this Swift port.
///
/// Vectors: CrossCompatWireVectors.swift, GENERATED by tools/govectors
/// (`cd tools/govectors && go run . -swift ../../tests/tests/crosscompat/CrossCompatWireVectors.swift > vectors.json`).
/// Fixture tree (fixed names, fixed bytes, CreateDag(path, false) => deterministic CIDs):
///
///     golden-repo/
///     ├── readme.md      = "hello golden repos"   (18 bytes)
///     └── docs/guide.md  = "swift parity guide"   (18 bytes)
///
/// Wire truths pinned here — the exact facts the Nosis mobile client depends on:
///  1. Per-leaf ContentSize/DagSize are NEVER populated by Go's BuildLeaf:
///     file leaves ride the wire with ContentSize=0 even when Content is
///     present; only BuildRootLeaf computes root-leaf aggregates. (This is the
///     wire truth behind the mobile "Zero KB" / "verified bytes do not match
///     authenticated file size" bug — and per-leaf ContentSize is not covered
///     by the leaf CID either, so it can never be an authentication input.)
///  2. Legacy batched packets carry Leaves + Relationships only. Current packets
///     add PacketIndex + TotalPackets as transport metadata, while tolerant decoders
///     preserve compatibility by treating their absence as zero.
///  3. Leaf CBOR keys are Go's PascalCase field names plus "stored_proofs".
///  4. The Swift builder reproduces the Go root CID for the identical tree.
final class CrossCompatWireTests: XCTestCase {

    /// Ordered CBOR keys of a serialized DagLeaf — fxamacker/cbor emits Go
    /// struct fields in declaration order, and Swift's serializableDagLeafToCBOR
    /// mirrors it. "stored_proofs" (the only tagged field) is appended when a
    /// leaf carries Merkle proofs.
    private static let goLeafKeyOrder = [
        "Hash", "ItemName", "Type", "ContentHash", "Content", "ClassicMerkleRoot",
        "CurrentLinkCount", "LeafCount", "ContentSize", "DagSize", "Links", "AdditionalData",
    ]

    // MARK: - Golden Go v2.2.6 vectors decoded by Swift

    func testGoSkeletonVector_DecodesVerifiesAndCarriesNoPerLeafSizes() throws {
        let receiver = try receiveGoldenPackets(CrossCompatWireVectors.skeletonPacketsHex)
        XCTAssertEqual(receiver.root, CrossCompatWireVectors.root,
            "🔴 Swift rebuilt a different root from Go's skeleton wire bytes!")
        XCTAssertEqual(receiver.leafs.count, 4)
        XCTAssertFalse(receiver.isPartial())

        // Root-leaf aggregates come from Go's BuildRootLeaf.
        let root = try XCTUnwrap(receiver.leafs[CrossCompatWireVectors.root])
        XCTAssertEqual(root.itemName, "golden-repo")
        XCTAssertEqual(root.type, .directory)
        XCTAssertEqual(root.leafCount, 4, "LeafCount is a root-only aggregate")
        XCTAssertEqual(root.contentSize, 36, "root ContentSize aggregate = 18 + 18 fixture bytes")
        XCTAssertGreaterThan(root.dagSize, 0)

        // Every NON-root leaf — including real files — carries zero sizes on the
        // deployed wire, because Go's BuildLeaf never populates them.
        for (hash, leaf) in receiver.leafs where hash != receiver.root {
            XCTAssertEqual(leaf.contentSize, 0, "\(leaf.itemName): Go BuildLeaf never populates per-leaf ContentSize")
            XCTAssertEqual(leaf.dagSize, 0, "\(leaf.itemName): Go BuildLeaf never populates per-leaf DagSize")
            XCTAssertEqual(leaf.leafCount, 0, "\(leaf.itemName): LeafCount is a root-only aggregate")
            XCTAssertNil(leaf.content, "\(leaf.itemName): the skeleton stream is content-free")
        }

        let readme = try XCTUnwrap(receiver.leafs[CrossCompatWireVectors.readmeLeafHash])
        XCTAssertEqual(readme.itemName, "readme.md")
        XCTAssertEqual(readme.type, .file)
        XCTAssertNotNil(readme.contentHash, "the CID-covered ContentHash is the real authentication input")
    }

    func testGoSelectedLeafVector_DeliversVerifiedContentWithZeroContentSize() throws {
        let receiver = try receiveGoldenPackets(CrossCompatWireVectors.selectedLeafPacketsHex)
        XCTAssertEqual(receiver.root, CrossCompatWireVectors.root)
        XCTAssertEqual(receiver.leafs.count, 2, "pruned selected-leaf DAG = root + readme leaf")
        XCTAssertTrue(receiver.isPartial())

        let root = try XCTUnwrap(receiver.leafs[CrossCompatWireVectors.root])
        XCTAssertFalse(root.proofs.isEmpty,
            "the pruned root must carry the readme Merkle proof (wire key stored_proofs)")

        let readme = try XCTUnwrap(receiver.leafs[CrossCompatWireVectors.readmeLeafHash])
        XCTAssertEqual(readme.content, try dataFromHex(CrossCompatWireVectors.readmeContentHex),
            "🔴 verified file content does not match the Go fixture bytes!")
        // THE deployed truth behind the mobile bug: the content is present and
        // Merkle-verified, yet ContentSize is STILL 0 — the protocol never
        // populates per-leaf sizes, so 0 means "unknown", not "empty".
        XCTAssertEqual(readme.contentSize, 0)
        XCTAssertEqual(readme.dagSize, 0)
        XCTAssertNotNil(readme.contentHash)
    }

    // MARK: - Wire shape (keys) parity, Go bytes and Swift bytes

    func testBatchedPacketWireShape_PreservesLegacyAndMatchesCurrentGo() throws {
        let decoder = CBORDecoder()

        // Deployed golden bytes remain valid legacy packets with no counters.
        for hexPacket in CrossCompatWireVectors.skeletonPacketsHex + CrossCompatWireVectors.selectedLeafPacketsHex {
            let packetMap = try XCTUnwrap(decoder.decode(try dataFromHex(hexPacket)).mapValue)
            XCTAssertEqual(packetMap.pairs.map(\.key), ["Leaves", "Relationships"])
            try assertLeafKeyOrder(in: packetMap)
        }

        // Current Go and Swift encoders include deterministic transport counters.
        let repoDir = try makeGoldenRepoDirectory()
        defer { try? FileManager.default.removeItem(atPath: repoDir.base) }
        let built = try ScionicMerkleTree.createDag(path: repoDir.repo, timestampRoot: false)
        let batches = built.getBatchedLeafSequence()
        XCTAssertFalse(batches.isEmpty)
        for (index, batch) in batches.enumerated() {
            let packetMap = try XCTUnwrap(decoder.decode(batch.toCBOR()).mapValue)
            XCTAssertEqual(packetMap.pairs.map(\.key), ["Leaves", "Relationships", "PacketIndex", "TotalPackets"])
            XCTAssertEqual(packetMap["PacketIndex"]?.intValue, index)
            XCTAssertEqual(packetMap["TotalPackets"]?.intValue, batches.count)
            try assertLeafKeyOrder(in: packetMap)
        }
    }

    func testBatchedPacketFromCBOR_ToleratesAbsentCounters() throws {
        // Historical Go wire bytes do not contain PacketIndex/TotalPackets; the tolerant
        // decoder must surface them as 0 so mixed-version peers use stop-and-wait fallback.
        // Current counter-bearing packets negotiate bounded sliding-window transport.
        for hexPacket in CrossCompatWireVectors.skeletonPacketsHex + CrossCompatWireVectors.selectedLeafPacketsHex {
            let packet = try BatchedTransmissionPacket.fromCBOR(try dataFromHex(hexPacket))
            XCTAssertEqual(packet.packetIndex, 0)
            XCTAssertEqual(packet.totalPackets, 0)
            XCTAssertFalse(packet.leaves.isEmpty)
            XCTAssertEqual(packet.relationships.count, packet.leaves.count)
        }
    }

    // MARK: - Builder parity

    func testBuildLeaf_LeavesSizesUnpopulated_AndBuildRootLeafAggregates() throws {
        // Non-root file leaf WITH content: sizes must stay 0 (Go BuildLeaf parity).
        // Populating them here would silently diverge the port from every deployed
        // desktop/relay build.
        let fileBuilder = DagLeafBuilder(name: "hello.txt")
        fileBuilder.setType(.file)
        fileBuilder.setData(Data("hello golden repos".utf8))
        let fileLeaf = try fileBuilder.buildLeaf(additionalData: nil)
        XCTAssertEqual(fileLeaf.contentSize, 0, "Go BuildLeaf parity: per-leaf ContentSize is never populated")
        XCTAssertEqual(fileLeaf.dagSize, 0, "Go BuildLeaf parity: per-leaf DagSize is never populated")
        XCTAssertEqual(fileLeaf.leafCount, 0)
        XCTAssertNotNil(fileLeaf.contentHash)

        // Root leaf: BuildRootLeaf computes the aggregates.
        let dagBuilder = DagBuilder()
        dagBuilder.addLeaf(fileLeaf, parent: nil)
        let rootBuilder = DagLeafBuilder(name: "golden-root")
        rootBuilder.setType(.directory)
        rootBuilder.addLink(fileLeaf.hash)
        let rootLeaf = try rootBuilder.buildRootLeaf(dag: dagBuilder, additionalData: nil)
        XCTAssertEqual(rootLeaf.leafCount, 2)
        XCTAssertEqual(rootLeaf.contentSize, 18, "root aggregate = total content bytes")
        XCTAssertGreaterThan(rootLeaf.dagSize, 0)
    }

    func testSwiftBuilder_ReproducesGoldenGoRoot() throws {
        // The golden bytes were captured from deployed Go v2.2.6 — pre-fastcdc,
        // so its root is an untagged fixed-2m cut. Pin the legacy mode this
        // vector was built under: the fastcdc-v1 default stamps a root
        // "chunking" tag, which changes the root CID by design (the fixture's
        // 18-byte files chunk identically either way — only the tag differs).
        setChunkSize(defaultChunkSize)
        defer { setDefaultChunkSize() }

        let repoDir = try makeGoldenRepoDirectory()
        defer { try? FileManager.default.removeItem(atPath: repoDir.base) }
        let built = try ScionicMerkleTree.createDag(path: repoDir.repo, timestampRoot: false)
        try built.verify()
        XCTAssertEqual(built.root, CrossCompatWireVectors.root,
            "🔴🔴🔴 Swift createDag produced a different root than deployed Go v2.2.6 for the identical tree! 🔴🔴🔴")
        let readme = try XCTUnwrap(built.leafs.values.first { $0.itemName == "readme.md" })
        XCTAssertEqual(readme.hash, CrossCompatWireVectors.readmeLeafHash)
    }

    // MARK: - Helpers

    /// Decodes and applies golden packets exactly like a receiving client:
    /// fromCBOR -> applyAndVerifyBatchedTransmissionPacket -> full verify().
    private func receiveGoldenPackets(_ hexPackets: [String]) throws -> Dag {
        XCTAssertFalse(hexPackets.isEmpty)
        let receiver = Dag()
        for hexPacket in hexPackets {
            let packet = try BatchedTransmissionPacket.fromCBOR(try dataFromHex(hexPacket))
            try receiver.applyAndVerifyBatchedTransmissionPacket(packet)
        }
        try receiver.verify()
        return receiver
    }

    private func assertLeafKeyOrder(in packetMap: CBOROrderedMap) throws {
        for leafValue in try XCTUnwrap(packetMap["Leaves"]?.arrayValue) {
            let leafMap = try XCTUnwrap(leafValue.mapValue)
            var expected = Self.goLeafKeyOrder
            if leafMap.pairs.contains(where: { $0.key == "stored_proofs" }) {
                expected.append("stored_proofs")
            }
            XCTAssertEqual(leafMap.pairs.map(\.key), expected,
                "leaf CBOR keys must be Go's PascalCase field names (+ tagged stored_proofs)")
        }
    }

    /// Recreates the generator's fixture tree byte for byte.
    private func makeGoldenRepoDirectory() throws -> (base: String, repo: String) {
        let base = try ParityTestHelpers.makeTempDir("wire_golden")
        let repo = ParityTestHelpers.join(base, "golden-repo")
        try ParityTestHelpers.writeData(ParityTestHelpers.join(repo, "readme.md"), Data("hello golden repos".utf8))
        try ParityTestHelpers.writeData(ParityTestHelpers.join(repo, "docs", "guide.md"), Data("swift parity guide".utf8))
        return (base, repo)
    }

    private func dataFromHex(_ hex: String) throws -> Data {
        let characters = Array(hex)
        XCTAssertEqual(characters.count % 2, 0, "hex string must have an even length")
        var data = Data(capacity: characters.count / 2)
        var index = 0
        while index + 1 < characters.count {
            let byte = try XCTUnwrap(UInt8(String(characters[index ... index + 1]), radix: 16),
                "invalid hex byte at offset \(index)")
            data.append(byte)
            index += 2
        }
        return data
    }
}
